CREATE OR REPLACE FUNCTION protect_completed_packing_order() RETURNS trigger AS  BEGIN IF OLD.status = 'completed' AND NEW.status = 'completed' THEN IF OLD.carton_count IS DISTINCT FROM NEW.carton_count THEN RAISE EXCEPTION 'carton_count changed'; ELSIF OLD.net_weight_per_carton IS DISTINCT FROM NEW.net_weight_per_carton THEN RAISE EXCEPTION 'net_weight changed'; ELSIF OLD.gross_weight_per_carton IS DISTINCT FROM NEW.gross_weight_per_carton THEN RAISE EXCEPTION 'gross_weight changed'; ELSIF OLD.fruit_type_id IS DISTINCT FROM NEW.fruit_type_id THEN RAISE EXCEPTION 'fruit_type_id changed'; ELSIF OLD.batch_id IS DISTINCT FROM NEW.batch_id THEN RAISE EXCEPTION 'batch_id changed'; END IF; END IF; RETURN NEW; END;  LANGUAGE plpgsql;
